#include <atomic>
#include <cstdlib>
#include <cstdio>
#include <new>
#include <memory_resource>
#include <jsoncons/json.hpp>
#include <jsoncons_ext/jsonschema/jsonschema.hpp>
static std::atomic<bool> measure{false};
static std::atomic<std::size_t> calls{0},bytes{0};
void* operator new(std::size_t n) {
    if(measure.load()){++calls;bytes+=n;}
    if(void* p=std::malloc(n?n:1)) return p;
    throw std::bad_alloc();
}
void* operator new[](std::size_t n){return ::operator new(n);}
void operator delete(void* p) noexcept {std::free(p);}
void operator delete[](void* p) noexcept {std::free(p);}
void operator delete(void* p,std::size_t) noexcept {std::free(p);}
void operator delete[](void* p,std::size_t) noexcept {std::free(p);}
int main(){
    alignas(std::max_align_t) static char arena[1024*1024];
    std::pmr::monotonic_buffer_resource pool(arena,sizeof(arena),std::pmr::null_memory_resource());
    auto* old=std::pmr::set_default_resource(&pool);
    using Json=jsoncons::pmr::json;
    int result=0;
    {
        auto sch=Json::parse(R"({"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"name":{"type":"string","pattern":"^[a-z]+$"}},"required":["name"],"additionalProperties":false})");
        auto instance=Json::parse(R"({"name":"abcdefghijklmnopqrstuvwxyz"})");
        auto compiled=jsoncons::jsonschema::make_json_schema(std::move(sch));
        calls=0;bytes=0;measure=true;
        const bool valid=compiled.is_valid(instance);
        measure=false;
        std::printf("valid=%d outside_pmr_allocations=%zu outside_pmr_requested_bytes=%zu\n",valid?1:0,calls.load(),bytes.load());
        // Dependency gate: every hostile-input validation allocation must be bounded.
        result=valid&&calls.load()==0?0:1;
    }
    std::pmr::set_default_resource(old);
    return result;
}

