#include <zlib.h>
#include <png.h>
#include <utf8proc.h>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <cstdint>
#include <cstddef>
struct Budget {std::size_t live=0,peak=0,cap=1024*1024,calls=0,fail=0;};
// MSVC max_align_t is 8 but its jmp_buf needs malloc's 16-byte alignment.
// A two-word header preserves the underlying malloc alignment on x64.
struct alignas(std::max_align_t) Header {std::size_t size;std::size_t reserved=0;};
static void* alloc(Budget* b,std::size_t n){
    if(++b->calls==b->fail||n>b->cap-b->live||n>SIZE_MAX-sizeof(Header))return nullptr;
    auto* h=static_cast<Header*>(std::malloc(sizeof(Header)+n));if(!h)return nullptr;
    h->size=n;b->live+=n;if(b->live>b->peak)b->peak=b->live;return h+1;
}
static void release(Budget* b,void* p){if(p){auto* h=static_cast<Header*>(p)-1;b->live-=h->size;std::free(h);}}
static voidpf za(voidpf ctx,uInt count,uInt size){if(size&&count>SIZE_MAX/size)return nullptr;return alloc(static_cast<Budget*>(ctx),std::size_t(count)*size);}
static void zf(voidpf ctx,voidpf p){release(static_cast<Budget*>(ctx),p);}
static png_voidp pa(png_structp p,png_alloc_size_t n){return alloc(static_cast<Budget*>(png_get_mem_ptr(p)),n);}
static void pf(png_structp p,png_voidp ptr){release(static_cast<Budget*>(png_get_mem_ptr(p)),ptr);}
struct Input {unsigned char* p;std::size_t n,pos;};
static void readpng(png_structp p,png_bytep out,png_size_t n){auto* in=static_cast<Input*>(png_get_io_ptr(p));if(n>in->n-in->pos)png_error(p,"truncated");std::memcpy(out,in->p+in->pos,n);in->pos+=n;}
static void quiet(png_structp,const char*){}
static int pngcase(Budget* budget,unsigned char* data,std::size_t size){
    png_structp p=png_create_read_struct_2(PNG_LIBPNG_VER_STRING,nullptr,nullptr,quiet,budget,pa,pf);
    if(!p)return 0;
    png_infop info=png_create_info_struct(p);if(!info){png_destroy_read_struct(&p,nullptr,nullptr);return 0;}
    if(setjmp(png_jmpbuf(p))){png_destroy_read_struct(&p,&info,nullptr);return 0;}
    Input input{data,size,0};png_set_read_fn(p,&input,readpng);png_set_user_limits(p,8192,8192);png_set_chunk_malloc_max(p,65536);png_set_chunk_cache_max(p,128);
    png_read_info(p,info);if(png_get_image_width(p,info)!=1||png_get_image_height(p,info)!=1)png_error(p,"dimensions");
    unsigned char row[16]{};if(png_get_rowbytes(p,info)>sizeof(row))png_error(p,"row cap");
    png_read_row(p,row,nullptr);png_read_end(p,info);png_destroy_read_struct(&p,&info,nullptr);return 1;
}
int main(int argc,char** argv){
    std::setvbuf(stdout,nullptr,_IONBF,0);
    if(argc!=2)return 2;
    unsigned char file[1024]{};FILE* f=nullptr;
    if(fopen_s(&f,argv[1],"rb")||!f)return 2;
    const auto n=std::fread(file,1,sizeof(file),f);std::fclose(f);
    std::printf("PNG probe start bytes=%zu\n",n);
    Budget b;int good=pngcase(&b,file,n);if(!good||b.live)return 3;
    const auto count=b.calls;std::printf("PNG real decode PASS calls=%zu peak=%zu\n",count,b.peak);
    for(std::size_t i=1;i<=count;++i){Budget failure;failure.fail=i;(void)pngcase(&failure,file,n);if(failure.live)return 4;}
    Budget limited;limited.cap=1;if(pngcase(&limited,file,n)||limited.live)return 5;
    std::printf("PNG each allocation-failure cut and one-byte cap PASS\n");
    const unsigned char text[]="bounded deflate payload";unsigned char packed[128]{},out[128]{};uLongf length=sizeof(packed);
    if(compress(packed,&length,text,sizeof(text))!=Z_OK)return 6;
    Budget zb;z_stream s{};s.zalloc=za;s.zfree=zf;s.opaque=&zb;
    if(inflateInit(&s)!=Z_OK)return 7;s.next_in=packed;s.avail_in=static_cast<uInt>(length);s.next_out=out;s.avail_out=sizeof(out);
    auto code=inflate(&s,Z_FINISH);inflateEnd(&s);if(code!=Z_STREAM_END||zb.live||std::memcmp(text,out,sizeof(text)))return 8;
    Budget denied;denied.cap=1;z_stream z{};z.zalloc=za;z.zfree=zf;z.opaque=&denied;
    if(inflateInit(&z)!=Z_MEM_ERROR||denied.live)return 9;
    std::printf("zlib real inflate PASS peak=%zu; allocation cap PASS\n",zb.peak);
    utf8proc_int32_t work[8192]{};const unsigned char input[]={0x53,0x74,0x72,0x61,0xc3,0x9f,0x65};
    auto options=UTF8PROC_STABLE|UTF8PROC_COMPOSE|UTF8PROC_CASEFOLD;
    auto length32=utf8proc_decompose(input,sizeof(input),work,8192,options);if(length32<0||length32>8192)return 10;
    auto bytes=utf8proc_reencode(work,length32,options);if(bytes!=7||std::memcmp(work,"strasse",7))return 11;
    const unsigned char invalid[]={0xc0,0xaf};if(utf8proc_decompose(invalid,2,work,8192,options)>=0)return 12;
    if(utf8proc_decompose(input,sizeof(input),work,1,options)<=1)return 13;
    std::printf("utf8proc bounded caller-buffer normalization/casefold/invalid-UTF8/required-size PASS\n");
    return 0;
}
